  name: 'anonymous',
  email: 'user@example.com',
  age: +0
): { name: 'anonymous', email: 'user@example.com', age: 0 } {
  return { name, email, age }
}

function transfer(
  from: '',
  to: '',
  amount: 0.0
): { from: '', to: '', amount: 0.0 } {
  return { from, to, amount }
}

